/**
 * GMimeTnefAttributeLevel:
 * @GMIME_TNEF_ATTRIBUTE_LEVEL_MESSAGE: The attribute is a message-level attribute.
 * @GMIME_TNEF_ATTRIBUTE_LEVEL_ATTACHMENT: The attribute is an attachment-level attribute.
 *
 * TNEF attribute level values.
 **/
typedef enum {
	GMIME_TNEF_ATTRIBUTE_LEVEL_MESSAGE = 1,
	GMIME_TNEF_ATTRIBUTE_LEVEL_ATTACHMENT = 2
} GMimeTnefAttributeLevel;

/**
 * GMimeTnefAttributeType:
 * @GMIME_TNEF_ATTRIBUTE_TYPE_TRIPLES: The value is a structure of recipient or sender information.
 * @GMIME_TNEF_ATTRIBUTE_TYPE_STRING: The value is a null-terminated string of 8-bit characters.
 * @GMIME_TNEF_ATTRIBUTE_TYPE_TEXT: The value is a block of 8-bit text.
 * @GMIME_TNEF_ATTRIBUTE_TYPE_DATE: The value is a 14-byte date structure.
 * @GMIME_TNEF_ATTRIBUTE_TYPE_SHORT: The value is a 16-bit integer.
 * @GMIME_TNEF_ATTRIBUTE_TYPE_LONG: The value is a 32-bit integer.
 * @GMIME_TNEF_ATTRIBUTE_TYPE_BYTE: The value is a block of binary data.
 * @GMIME_TNEF_ATTRIBUTE_TYPE_WORD: The value is an unsigned 16-bit integer.
 * @GMIME_TNEF_ATTRIBUTE_TYPE_D_WORD: The value is an unsigned 32-bit integer.
 *
 * TNEF attribute type values.
 **/
typedef enum {
	GMIME_TNEF_ATTRIBUTE_TYPE_TRIPLES = 0,
	GMIME_TNEF_ATTRIBUTE_TYPE_STRING = 0x00010000,
	GMIME_TNEF_ATTRIBUTE_TYPE_TEXT = 0x00020000,
	GMIME_TNEF_ATTRIBUTE_TYPE_DATE = 0x00030000,
	GMIME_TNEF_ATTRIBUTE_TYPE_SHORT = 0x00040000,
	GMIME_TNEF_ATTRIBUTE_TYPE_LONG = 0x00050000,
	GMIME_TNEF_ATTRIBUTE_TYPE_BYTE = 0x00060000,
	GMIME_TNEF_ATTRIBUTE_TYPE_WORD = 0x00070000,
	GMIME_TNEF_ATTRIBUTE_TYPE_D_WORD = 0x00080000
} GMimeTnefAttributeType;

