/**
 * GMimeTnefPropertyType:
 * @GMIME_TNEF_PROPERTY_TYPE_UNSPECIFIED: The type of the property is unspecified.
 * @GMIME_TNEF_PROPERTY_TYPE_NULL: The property has a null value.
 * @GMIME_TNEF_PROPERTY_TYPE_I2: The property has a signed 16-bit value.
 * @GMIME_TNEF_PROPERTY_TYPE_LONG: The property has a signed 32-bit value.
 * @GMIME_TNEF_PROPERTY_TYPE_R4: The property has a 32-bit floating point value.
 * @GMIME_TNEF_PROPERTY_TYPE_DOUBLE: The property has a 64-bit floating point value.
 * @GMIME_TNEF_PROPERTY_TYPE_CURRENCY: The property has a 64-bit integer value representing 1/10000th of a monetary unit (i.e., 1/100th of a cent).
 * @GMIME_TNEF_PROPERTY_TYPE_APP_TIME: An OLE Automation date stored as a double.
 * @GMIME_TNEF_PROPERTY_TYPE_ERROR: The property has a 32-bit error value.
 * @GMIME_TNEF_PROPERTY_TYPE_BOOLEAN: The property has a boolean value.
 * @GMIME_TNEF_PROPERTY_TYPE_OBJECT: The property has an embedded object value.
 * @GMIME_TNEF_PROPERTY_TYPE_I8: The property has a signed 64-bit value.
 * @GMIME_TNEF_PROPERTY_TYPE_STRING8: The property has a null-terminated 8-bit character string value.
 * @GMIME_TNEF_PROPERTY_TYPE_UNICODE: The property has a null-terminated unicode character string value.
 * @GMIME_TNEF_PROPERTY_TYPE_SYS_TIME: The property has a 64-bit integer value specifying the number of 100ns periods since Jan 1, 1601.
 * @GMIME_TNEF_PROPERTY_TYPE_CLASS_ID: The property has an OLE GUID value.
 * @GMIME_TNEF_PROPERTY_TYPE_BINARY: The property has a binary blob value.
 * @GMIME_TNEF_PROPERTY_TYPE_MULTI_VALUED: A flag indicating that the property contains multiple values.
 *
 * TNEF property type values.
 **/
typedef enum {
	GMIME_TNEF_PROPERTY_TYPE_UNSPECIFIED = 0,
	GMIME_TNEF_PROPERTY_TYPE_NULL = 1,
	GMIME_TNEF_PROPERTY_TYPE_I2 = 2,
	GMIME_TNEF_PROPERTY_TYPE_LONG = 3,
	GMIME_TNEF_PROPERTY_TYPE_R4 = 4,
	GMIME_TNEF_PROPERTY_TYPE_DOUBLE = 5,
	GMIME_TNEF_PROPERTY_TYPE_CURRENCY = 6,
	GMIME_TNEF_PROPERTY_TYPE_APP_TIME = 7,
	GMIME_TNEF_PROPERTY_TYPE_ERROR = 10,
	GMIME_TNEF_PROPERTY_TYPE_BOOLEAN = 11,
	GMIME_TNEF_PROPERTY_TYPE_OBJECT = 13,
	GMIME_TNEF_PROPERTY_TYPE_I8 = 20,
	GMIME_TNEF_PROPERTY_TYPE_STRING8 = 30,
	GMIME_TNEF_PROPERTY_TYPE_UNICODE = 31,
	GMIME_TNEF_PROPERTY_TYPE_SYS_TIME = 0x00000040,
	GMIME_TNEF_PROPERTY_TYPE_CLASS_ID = 0x00000048,
	GMIME_TNEF_PROPERTY_TYPE_BINARY = 0x00000102,
	GMIME_TNEF_PROPERTY_TYPE_MULTI_VALUED = 0x00001000
} GMimeTnefPropertyType;

